quests[45065] = { id = 45065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadtvermessung", description = "Hier wird es nie langweilig! Nun... vielleicht ist das nicht ganz wahr.\n\nIch fürchte, ich muss Euch bitten, noch einmal zur Stadt zurückzukehren und Informationen zu sammeln. Aber nicht irgendwelche Informationen... Ich brauche ganz bestimmte Angaben!\n\nIch brauche bestimmte Koordinaten, um meine Teleportationen mit äußerster Genauigkeit fokussieren zu können. Wenn wir die Informationen haben, wird es leider noch eine ganze Weile dauern, bis wir sie durchgegangen sind. Doch in der Zwischenzeit haben wir ohnehin noch einiges zu tun.", sourceObjective = "Verwendet den verbesserten telemantischen Signalgeber, um die Terrasse der Ordnung in Suramar zu vermessen.", completion = "Ich werde diese Daten sofort analysieren.\n\nAber jetzt müssen wir uns erst einmal... <Oculeth bringt nacheinander seine Fingerspitzen zusammen.>\n\n...interessanten technologischen Fortschritten widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45066] = { id = 45066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentelle Instabilität", description = "Um unsere Forschungen voranzubringen, muss ich Euch bitten, ein paar ganz bestimmte Gegenstände aus meiner lange verlassenen Unterkunft zu beschaffen.\n\nIch versichere Euch, dass es dort... größtenteils sicher ist. Abgesehen von ein paar instabilen Elementen.\n\nBegebt Euch in meine Werkstatt und sucht den Teleporter. Ich werde die Tarnvorrichtung abschalten, sobald Ihr ankommt.", sourceObjective = "Sammelt die Telemantieaufzeichnungen und 4 zurückgelassene Kugeln in Oculeths Testkammer.", completion = "Wunderbar! Jetzt geht der Spaß los. Ihr solltet mit Thalyssra sprechen. Ich glaube, sie ist bereit für weitere... Tests.", sourceObjectiveStatus = "unverified-source-field" }
quests[45067] = { id = 45067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telemantische Weiten", description = "Möglicherweise reicht das Verständnis der Teufelsmagie allein noch nicht aus, {name}.\n\nSprecht mit Oculeth darüber, wie wir unsere Bemühungen ausweiten können. Ich habe gehört, er hätte etwas... Einzigartiges mit uns vor.", sourceObjective = "Sprecht mit Oculeth in Shal'Aran.", completion = "Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45068] = { id = 45068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fässerweise Spaß" }
