quests[45072] = { id = 45072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fässerweise Spaß" }
quests[45073] = { id = 45073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandschatzen und fette Beute!", description = "Ich will ganz ehrlich sein. Ich hab nämlich meine ganz eigenen Gründe, um hier zu sein. Letztes Mal gab's ein kleines Debakel mit zu viel Suff, zu viel Glücksspiel und 'n bisschen zu viel Rum... Ihr wisst schon, was ich meine. Ein Wort gab das andere, Fäuste flogen und... es war 'n ganz schönes Durcheinander. Und seitdem bin ich hier nicht mehr der willkommenste Pirat.\n\nAber sie haben mir meine Sachen abgenommen, diese lügenden, dreckigen... ähem. Könntet Ihr wohl diese Fackel nehmen und... ihren Besitz abfackeln? Ich wäre Euch sehr dankbar.", sourceObjective = "Fackelt 8 Beutefässer der Schwarzsegel ab.", completion = "Ich danke Euch. Ich fühl mich besser, wenn ich weiß, dass ich gerächt wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[45079] = { id = 45079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dorf Schluchtbach", description = "<Dieses Buch ist ein Verzeichnis aller Einwohner von Schluchtbach.\n\nBis auf ein paar wenige Namen sind alle durchgestrichen.>", sourceObjective = "Findet heraus, welches Schicksal die Bewohner von Schluchtbach ereilt hat.", completion = "<Annie sieht Euch mit leerem Blick an. Ihre Kleidung ist blutverschmiert, aber sie selbst scheint größtenteils unversehrt zu sein. Sie stottert ein paar unverständliche Worte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45083] = { id = 45083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crysas Flieger", description = "Ich habe einige der exotischsten Aasvögelspezies besorgt, die man je auf Azeroth gesehen hat. Glaubt Ihr, Ihr könnt gegen sie bestehen?", sourceObjective = "Besiegt Crysa in einem Haustierkampf.", progress = "Die Aasvögel kreisen Euch ein!", completion = "Überall sind Federn! Was für ein Chaos.", sourceObjectiveStatus = "unverified-source-field" }
quests[45088] = { id = 45088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung der Tapferkeit: Die verlorene Armee", description = "Helya auszuschalten, ist zwar Eure primäre Aufgabe, aber ich benötige noch weitere Hilfe von Euch. Helya hat die Fähigkeit erlangt, die Seelen meiner Valarjar zu stehlen und zu verderben. Ihre Schergen halten die Seelen gefangen und missbrauchen sie. Und ich bin mir sicher, dass Helya die Seelen der größten Valarjar für sich selbst beansprucht. Ihr müsst diese verlorenen Seelen retten und sie mir zurückbringen.\n\nWenn Euch das gelingt, werde ich Euch mit einem verzauberten Schutz aus der Waffenkammer der Hallen belohnen.", sourceObjective = "Sammelt 1000 Seelenfragmente der Valarjar innerhalb des Schlachtzugs \"Die Prüfung der Tapferkeit\".", progress = "Bringt mir die Seelen meiner verlorenen Valarjar. Nur dann werde ich Euch mit der gesegneten Rüstung belohnen, nach der es Euch verlangt.", completion = "Dank dieser Seelen, die Ihr in die Hallen der Tapferkeit zurückgebracht habt, sind meine Truppen wieder so stark wie früher. Wie versprochen gehört die Belohnung Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[45095] = { id = 45095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 001 - Crashed Horde Ship" }
quests[45096] = { id = 45096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 002 - Fel Cave" }
quests[45097] = { id = 45097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 003 - Puddle Cave" }
quests[45102] = { id = 45102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginnt den Angriff", description = "Der Kampf um unsere Welt wurde erbittert geführt, aber dank der Macht Eurer Waffe und mithilfe der vereinten Streitkräfte Azeroths haben wir die Invasionsmacht der Dämonen an allen Fronten zurückgeschlagen.\n\nNun stehen wir erneut an der Verheerten Küste und sind im Begriff, das zu tun, was wir zuvor nicht erreichen konnten. Lasst uns diejenigen nicht vergessen, die alles geopfert haben, um uns diese Chance zu eröffnen.\n\nUnser erstes Ziel ist es, den Hügel vor uns einzunehmen, damit wir eine Festung errichten können. Wappnet Euch, {name}. Der Angriff auf die Verheerte Küste beginnt jetzt.", sourceObjective = "Beginnt den Angriff auf die Verheerte Küste.", sourceObjectiveStatus = "unverified-source-field" }
quests[45103] = { id = 45103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten wir!", description = "Die Zeit ist gekommen, <Todesgebieter/Todesgebieterin>! Unsere Späher haben unweit von hier eine große Ansammlung Dämonen ausfindig gemacht. Führt uns zum Sieg und zeigt diesen Dämonen die Macht des Untodes!", sourceObjective = "Führt die Vier Reiter in den Kampf gegen die Brennende Legion.", completion = "Jetzt haben wir der Legion die Macht der Schwarzen Klinge gezeigt. Die Fähigkeit, so viele Dämonen auszuschalten, ohne den Tod fürchten zu müssen... das ist unsere Macht. Noch viele von ihnen werden unseren Klingen zum Opfer fallen. Wir werden sie für Azeroth niederstrecken.\n\nGeleidet Euch wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[45104] = { id = 45104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer nächster Auftrag...", sourceObjective = "[Create interesting treasures and vignettes for patch 7.2!]", sourceObjectiveStatus = "unverified-source-field" }
quests[45105] = { id = 45105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Raz'gor", description = "Der Grubenlord Raz'gor hat den Befehl über dieses Bollwerk. Wenn Ihr die Verheerte Küste einnehmen wollt, müsst Ihr Raz'gor bezwingen.\n\nKämpft Euch durch die Dämonenblockade und findet Lord Raz'gor. Wenn Ihr den Dämon ausschaltet, versetzt Ihr den Plänen der Brennenden Legion für die Verheerte Küste einen herben Schlag.", sourceObjective = "Besiegt Lord Raz'gor an der Verheerten Küste.", sourceObjectiveStatus = "unverified-source-field" }
quests[45110] = { id = 45110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 004 - Fel Tower 001" }
quests[45111] = { id = 45111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu einem guten Kampf sagt niemand nein", description = "Auf der Notiz steht:\n\n\"Ihr hättet nichts von den Kämpfen ausplaudern sollen, schon gar nicht zu diesen Champions. Aber da genau das geschehen ist, geht es wohl in Ordnung, wenn sie hin und wieder hier kämpfen. Aber Ihr beweist besser vorher, dass Ihr zu den echten Kämpfern zählt!\"", sourceObjective = "Tretet in 5 Kämpfen der Kampfgilde an.", completion = "Also gut, ich werde Eure Champions für die Kämpfe im Ring zulassen. Wenn sie einen Kampf gewinnen sollten, könnt Ihr wieder zu mir kommen. Dann werden wir sehen, ob wir sie vielleicht in härteren Kämpfen antreten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45112] = { id = 45112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Wahnsinns", description = "<Der unbekannte Käufer scheint in aller Eile aufgebrochen zu sein. In der Luft sind noch beißende Dämpfe wahrnehmbar und das Lagerfeuer in der Mitte des Bereichs glimmt noch.>\n\n<Vielleicht findet Ihr hier einen Hinweis darauf, wo ihr weitersuchen solltet?>", sourceObjective = "Durchsucht die Verlassene Werkstatt nach Informationen, die Euch zu dem Käufer führen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45116] = { id = 45116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer nächster Auftrag...", sourceObjective = "[Create interesting treasures and vignettes for patch 7.2!]", sourceObjectiveStatus = "unverified-source-field" }
quests[45117] = { id = 45117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TRACKING" }
quests[45118] = { id = 45118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helyas Horn", description = "{name}, wir werden unsere Armee auf jede erdenkliche Art verstärken müssen. Die Kvaldir sind unrettbar verflucht, aber sie sind leidenschaftliche Krieger und eine Ressource, die wir nicht außer Acht lassen sollten.\n\nSie sind für alle Zeiten daran gebunden, Helya zu gehorchen, auch jetzt, da sie tot ist. Wenn wir die Kvaldir mit Helyas Stimme rufen können, werden sie stattdessen uns folgen!\n\nWir haben Helyas Horn von ihrer Leiche geborgen. Erfüllt es mit Macht, damit Ihr die Kvaldir herbeirufen könnt, wenn wir sie benötigen.", sourceObjective = "Tötet Feinde in Helheim, um Helyas Horn mit Macht zu erfüllen.", completion = "Rache ist süß. Die Kvaldir werden jetzt gezwungen sein, uns zu gehorchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45119] = { id = 45119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 005 - Fel Tower 002" }
quests[45120] = { id = 45120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 019 - Ruined Temple 002" }
quests[45121] = { id = 45121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 006 - Pillar 001" }
quests[45122] = { id = 45122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 007 - Back Beach" }
quests[45123] = { id = 45123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementar: Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie im Sacellum der Schreiber gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", completion = "Es scheint, als ob Levia der Verführung eines Sukkubus verfallen ist. Ich fürchte, ihre Zeit als einsame Ausgestoßene hat sie wohl für derartige Winkelzüge empfänglich gemacht. Ich kann nicht umhin, mich irgendwie schuldig zu fühlen, dass sie diesen Weg eingeschlagen hat.\n\nJedenfalls befindet sich Levia in großer Gefahr. Sie muss gefunden werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[45125] = { id = 45125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonischer Dilettantismus", description = "Levia muss diese Runen bei ihrem Ritual benutzt haben. Selbst wenn sie so mächtig ist, wie Modera sagt, war sie eine Anfängerin, was dämonische Magie angeht, also mussten die Runen helfen, das Portal zu stabilisieren.\n\nIhr müsst herausfinden, welche Runen aktiviert werden müssen, um ihr Ritual zu wiederholen. Es gibt einige Bücher über Runenmagie in diesem Raum, die sie zweifellos für ihr Ritual studiert hat.\n\nSobald Ihr die Runen aktiviert habt, werde ich den Zauber vollenden.", sourceObjective = "Aktiviert die drei richtigen Runen, um Ritssyn Flammengroll dabei zu helfen, den Zauber zur Stabilisierung des Portals zu vollenden.", progress = "Hört auf herumzualbern und helft mir bei diesem Ritual!", completion = "Ich bin angenehm überrascht, {class}. Hättet Ihr dieses Rätsel nicht so schnell gelöst, wäre Eure Magierfreundin an Agatha verloren gewesen.\n\nDas Portal ist stabilisiert und sollte uns zum Aufenthaltsort der Magierin führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45126] = { id = 45126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückte Verführung", description = "Mo... Modera hat Euch geschickt?\n\nNein... Ihr müsst... gehen! Agatha wird gleich zurück sein!\n\nRettet... Euch...", sourceObjective = "Besiegt Agatha.", progress = "Rettet... Euch...", completion = "Ekelerregend! Ich kann nicht glauben, dass mich diese Kreatur in ihren Bann schlagen konnte!\n\nIch war so eine Närrin! Sie hat mich glauben lassen, dass ich ihr etwas bedeuten würde. Ganz offensichtlich hatte ich keine Ahnung, wer Agatha wirklich war!", sourceObjectiveStatus = "unverified-source-field" }
quests[45127] = { id = 45127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe unter einem teuflischen Stern", description = "Diese widerwärtige Wichtelmutter! Wenn ich nicht so geschwächt wäre, würde ich sofort da reinspringen, um ihr eine schmerzhafte Lektion zu erteilen!\n\n<Levia atmet tief durch, um die Fassung zurückzuerlangen.>\n\nEs ist nur eine Frage der Zeit, bis Agatha die Macht einsetzen kann, die sie mir gestohlen hat. Und wenn es so weit ist, sollten wir lieber nicht hier sein.", sourceObjective = "Kehrt zu Erzmagierin Modera in Dalaran zurück.", completion = "Levia ist in Sicherheit? Da bin ich aber erleichtert, obwohl ich wünschte, wir hätten früher zu ihr vordringen können. Eine Wichtelmutter ist schon schlimm genug. Ich mag mir gar nicht ausmalen, zu was Agatha fähig ist, wenn sie auch noch über Levias Macht verfügt. Und wer weiß, welche Geheimnisse Levia preisgegeben hat, während sie unter ihrem Einfluss stand?\n\nIch fürchte, dieser Kampf ist noch nicht vorüber.\n\nEinstweilen sollten wir alle Siege, die wir erringen können, feiern. Ich danke Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[45128] = { id = 45128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine glorreiche Wiedervereinigung", description = "Ihr habt gute Arbeit geleistet, <Schlachtenfürst/Schlachtenfürstin> {name}. Lasst uns jetzt zur Himmelsfeste zurückkehren. Odyn wird von Euren Erfolgen hier hören wollen.", sourceObjective = "Sprecht mit Aerylia und erstattet dann Odyn Bericht.", completion = "Ihr habt meine Erwartungen sogar noch übertroffen, Schlachtenfürst {name}.", sourceObjectiveStatus = "unverified-source-field" }
