quests[45142] = { id = 45142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 012 - Behind Tomb of Sargeras" }
quests[45143] = { id = 45143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warten auf das Urteil", description = "Unsere anhaltende Offensive an der Verheerten Küsten hat das Interesse vieler Paladine geweckt, die unter Eurem Befehl kämpfen wollen. Einige von ihnen sind würdiger als andere, aber nur Ihr selbst könnt darüber entscheiden.\n\nDie neuen Rekruten warten im Lager außerhalb der Kapelle auf Euer Urteil.", sourceObjective = "Setzt 'Urteil des Hochlords' ein, um zu bestimmen, welche Rekruten der Silbernen Hand würdig sind.", completion = "Euer Urteil ist entschieden und gerecht, Hochlord.\n\nDiese neuen Rekruten werden viel unter Eurem Befehl lernen.\n\nObwohl ich mich wundere, wie es wohl um meine Würdigkeit bestellt wäre, wenn man mich prüfen würde?", sourceObjectiveStatus = "unverified-source-field" }
quests[45144] = { id = 45144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 013 - Ruined Temple" }
quests[45145] = { id = 45145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Familie Mondfang", description = "Wie versprochen ist hier der Mondsichelschlüssel, mit dem sich die Truhen meiner Familie öffnen lassen, auch wenn in ihnen nichts mehr von Wert zu finden ist.\n\nIch gehe davon aus, dass Ihr alles, was Ihr findet, zu Delas bringt? All unsere Familienrelikte sollten ungeachtet ihres Werts in unserer Familie verbleiben.", sourceObjective = "Bergt die Relikte der Familie Mondfang aus dem Schattenmoor.", completion = "Der Name Nerus ist mir bekannt, wir sind verwandt. Aber was hat er mit verderbten Schmuckstücken zu tun?\n\nDie Antwort darauf könnte in dieser Schriftrolle stecken, aber sie scheint unbeschrieben zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[45146] = { id = 45146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen lesen", description = "Dies ist eine besondere Schriftrolle: Für das ungeübte Auge scheint sie eine leere Seite darzustellen, aber wenn ich sie gegen das Licht halte, sehe ich kurz ein paar Runen aufleuchten.\n\nWie bei den meisten anderen dämonischen Runen auch benötige ich Teufelsblut, um die Magie aufzuheben, die die Botschaft dieser Schriftrolle verbirgt.", sourceObjective = "Sammelt 10 Einheiten Teufelsblut von Dämonen auf den Verheerten Inseln.", progress = "Ich muss die Schriftrolle in Dämonenblut eintauchen, um die Runen lesbar zu machen.", completion = "Die Runen sollten sehr schnell sichtbar werden, sobald ich sie mit dem gereinigten Blut behandle.", sourceObjectiveStatus = "unverified-source-field" }
quests[45147] = { id = 45147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelssteinzerstörung", description = "<Delas steht mit offenem Mund da, während die Schriftrolle ihren Händen entgleitet und zu Boden fällt.>\n\nDas... kann nicht sein. Diese Runen... Sie beschreiben eine Abmachung zwischen der Brennenden Legion und meinen Vorfahren. Der finstere Pakt besagt, dass meine Vorfahren in diesem Leben Schutz vor den Dämonen genießen, ihre Geister aber im Gegenzug der Legion gehören.\n\nDieser Teufelssteinanhänger ist die Verkörperung des Pakts und kann nach dem ersten Anlegen nicht mehr abgelegt werden.\n\nSchnell, {name}, Ihr müsst Euer Artefakt verwenden, um das verfluchte Schmuckstück zu zerstören!", sourceObjective = "Zerstört den Teufelssteinanhänger.", completion = "Wenn Ihr stark genug gewesen seid, um den Anhänger zu zerstören, der meinen Geist an die Brennende Legion gebunden hatte, gibt es vielleicht noch Hoffnung für meine Vorfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[45148] = { id = 45148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwurbrecher", description = "Vor vielen Jahren habe ich einen Pakt mit einem Mann abgeschlossen, von dem ich dachte, dass er mir ähnlich wäre. Er versprach Schutz. Ein Versprechen, das zu schön war, um wahr zu sein. Doch ich war verzweifelt und willigte ein.\n\nErst als wir den Pakt mit Blut besiegelt hatten, zeigte der Schreckenslord Zorak sein wahres Gesicht.\n\nSolange er lebt, sind meine Vorfahren an die Brennende Legion gebunden. So sammelt unser Feind eine riesige Armee unwilliger Krieger.\n\nBegebt Euch zur Verheerten Küste und tötet Schwurbinder Zorak. Sein Tod wird die Kontrolle brechen, die er über meine Vorfahren ausübt.", sourceObjective = "Begebt Euch zur Verheerten Küste und tötet Schwurbinder Zorak.", completion = "Jetzt, wo Zorak tot ist, sind die Geister meiner Vorfahren endlich von ihrem Fluch befreit.", sourceObjectiveStatus = "unverified-source-field" }
quests[45149] = { id = 45149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Halbmondfluchs", description = "Wir müssen tun, was wir können, um den Fluch zu brechen, der meine Ahnen befällt.\n\nDie Brennende Legion hat in den Ruinen, die unsere Toten beherbergen, ein Lager aufgeschlagen und ist bereit, den furchtbaren Pakt in die Tat umzusetzen, der vor so langer Zeit geschlossen wurde.\n\nJeder meiner Vorfahren trägt einen Anhänger, durch den sie an ihre dämonischen Herren gebunden werden. Man kann sie nicht abnehmen, aber wie Ihr bewiesen habt, kann man sie mit genügend Kraft zerstören.\n\nSetzt dem Fluch, der meine Vorfahren plagt, ein Ende und befreit ihre Geister.", sourceObjective = "Befreit dämonenversklavte Geister in den Halbmondruinen, indem Ihr ihre Teufelssteinanhänger zerstört.", completion = "Was Ihr für meine Familie getan habt, werden wir nie vergessen.\n\nDie Geister der Familie Mondfang werden für immer in Eurer Schuld stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45150] = { id = 45150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 013 - Fel Tower 003" }
quests[45151] = { id = 45151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 015 - Ritual Altar" }
quests[45152] = { id = 45152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 036 - Tomb Statue Book" }
