quests[45154] = { id = 45154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 017 - Egg Cave" }
quests[45158] = { id = 45158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 018 - Crashed Alliance Sea Ship" }
quests[45159] = { id = 45159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kubisches Rätsel", description = "<Ihr findet einen mysteriösen Würfel. Die Bauweise ist Euch nicht bekannt, aber er ist eindeutig uralt.\n\nDie Oberfläche des Würfels ist mit magischen Runen überzogen. Er ist zwar inaktiv, aber seine Eigenschaften könnten dennoch interessant sein.\n\nVielleicht solltet Ihr ihn zu Dariness der Gelehrten in Dalaran bringen, um mehr darüber zu erfahren.>", sourceObjective = "Bringt den mysteriösen Würfel zu Dariness der Gelehrten in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "<Dariness blickt fasziniert auf das ihr dargereichte Artefakt.>\n\nDas ist eine sehr interessante Bauweise! Er erinnert mich an eine uralte Kuriosität, über die ich im Verlauf meiner Ausbildung erfahren habe. Aber das kann eigentlich nicht sein, denn so ein Gerät wurde noch nie gefunden.\n\nHm, ich frage mich, ob es noch funktioniert. Und es gibt nur einen Weg, das herauszufinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[45160] = { id = 45160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kubische Ströme", description = "Um den Einsatzzweck dieses Würfels herauszufinden, müssen wir ihn mit Energie versorgen. Hm, ich habe da eine Idee...\n\nDie Nachtgeborenen schätzen eine Substanz, die wir uraltes Mana nennen und die Ihr sicherlich kennt. Für solch ein altes Relikt ist es wohl genau das Richtige. Besorgt eine ausreichende Menge davon, damit wir versuchen können, ihn zum Laufen zu bringen.\n\nAber passt gut auf Euch auf in Suramar! Es wäre ja eine Schande, wenn dieser kuriose Würfel verloren ginge und erneut nur eine blasse Erinnerung bliebe.", sourceObjective = "Beschafft 300 uraltes Mana aus Suramar.", completion = "Habt Ihr also ausreichend uraltes Mana gesammelt, um den Würfel damit zu versorgen?", sourceObjectiveStatus = "unverified-source-field" }
quests[45161] = { id = 45161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Special - 850 - Special - Brawlers - Fight 01 - Tracking Quest" }
quests[45162] = { id = 45162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer ist gefallen", description = "Eure Champions waren im Kampf gegen den Rat der Kriegshämmer erfolgreich. Bringt dieses \"Zeichen\" als Beweis zur Kampfgilde.", sourceObjective = "Begebt Euch zur Kampfgilde.", completion = "Die haben den Rat besiegt? Nicht schlecht. Dann sind sie wohl bereit für was Härteres.", sourceObjectiveStatus = "unverified-source-field" }
quests[45163] = { id = 45163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühjahrsputz", description = "Eure Champions waren erfolgreich. Sie erzählen ruhmreiche Geschichten darüber, wie sie Bill den Hausmeister des Hauses verwiesen haben.", sourceObjective = "Bringt den zerbrochenen Besenstiel zurück zur Kampfgilde.", completion = "Ihr glaubt, Ihr habt es drauf, weil Ihr einen Hausmeister besiegen konntet? Also gut, dann werde ich Euch mal für den nächsten Kampf zulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45164] = { id = 45164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Special - 850 - Special - Brawlers - Fight 02 - Tracking Quest" }
quests[45165] = { id = 45165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Brawlers - Fight 01 - Overmax Reward Credit - Tracking Quest" }
quests[45166] = { id = 45166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 020 - Murloc Beach Hut" }
quests[45167] = { id = 45167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "{name}, wir werden unsere Armee auf jede erdenkliche Art verstärken müssen, wenn wir auch nur einen Hoffnungsschimmer haben wollen, die Legion zurückzuschlagen. Die Kvaldir sind unrettbar verflucht, aber sie sind leidenschaftliche Krieger und eine Ressource, die wir nicht außer Acht lassen sollten. Sie müssen unweigerlich demjenigen gehorchen, der Helyas Horn besitzt. Ihr müsst es an Euch bringen. \n\nIhre sogenannten Helarjar hatten den Auftrag, es zu bewachen. Ihr werdet es ihnen abnehmen müssen.", sourceObjective = "Findet Helyas Horn.", sourceObjectiveStatus = "unverified-source-field" }
quests[45168] = { id = 45168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 021 - Above Puddle Cave" }
quests[45169] = { id = 45169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 022 - Hub Cliff" }
quests[45170] = { id = 45170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45171] = { id = 45171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Intro Mission - Tracking Quest" }
quests[45172] = { id = 45172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kampf!", description = "Eure Champions sind von der Erkundung des Schlachtfelds zurückgekehrt. Der Bericht erzählt von wilden Abenteuern und todesverachtenden Heldentaten, von Stärke und Ehre. In diesen hin und her wogenden Eroberungskämpfen ist weitere Unterstützung jederzeit willkommen.\n\nWerdet Ihr dem Ruf folgen?", sourceObjective = "Tretet einem beliebigen Schlachtfeld bei und gewinnt es.", completion = "Gut gemacht! Schlachtfelder sind wahrlich kein Platz für die Schwachen.\n\nNach Eurem Erfolg werden Eure Champions nun nach mehr Gelegenheiten für Euch Ausschau halten, Euren Wert zu beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45173] = { id = 45173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Zeiten", description = "Der Konflikt ist nicht beendet. Wie immer ist Eure Unterstützung auf den großen Schlachtfeldern erforderlich. Stürzt Euch in das Gemetzel, besiegt Eure Gegner und erntet Ruhm für Eure Fraktion.", sourceObjective = "Tretet einem beliebigen Schlachtfeld bei und gewinnt es.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[45174] = { id = 45174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach Illidan Sturmgrimm", description = "Allari die Seelenfresserin, ein Orakel der Illidari, ist schon seit einiger Zeit hinter Illidans Seele her. Sie glaubt, jetzt den Standort zu kennen und benötigt Eure Hilfe bei der Bergung.\n\nSucht Allari am Verteidigungsposten der Illidari in Azsuna auf und helft Ihr auf jede erdenkliche Weise.\n\nWenn Sargeras wirklich plant, Illidans Körper als Medium für seine eigene Rückkehr zu verwenden, ist es von höchster Wichtigkeit, Illidans Seele wieder mit seinem Körper zu vereinen, um zu verhindern, dass der Dunkle Titan seinen Weg in unsere Welt zurückfindet!", sourceObjective = "Sucht Allari die Seelenfresserin am Verteidigungsposten der Illidari in Azsuna auf.", completion = "Der Naaru hat mich erhört? Interessant...\n\nAlso gut, machen wir uns an die Arbeit. Wir haben endlich Illidans Seele gefunden. Und sie ist nicht da, wo wir sie vermutet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[45175] = { id = 45175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenprisma der Illidari", description = "Jedoch will ich Euch zu diesem Zeitpunkt noch nicht mit dem Wissen um den Standort der Seele des Meisters belasten, {name}. Zunächst müssen wir ein Seelenprisma herstellen, das den mächtigen chaotischen Energien des Meisters standhalten kann.\n\nUnd dazu benötige ich verweilende Seelenfragmente von mächtigen Wesen, die über diese ganze Welt verstreut sind. Wenn Ihr mir genug davon bringen könnt, werde ich ein Seelenprisma erschaffen, das die Seele des Meisters aufnehmen kann. Zumindest für die Dauer des Transfers in den Naaru.", sourceObjective = "Besorgt 5 verweilende Seelenfragmente von den Endbossen in Dungeons von Legion.\n\nDungeons mit höherem Schwierigkeitsgrad bieten eine größere Chance auf verweilende Seelenfragmente und eine höhere Anzahl davon.", completion = "Das Seelenprisma der Illidari ist einsatzbereit.\n\nIllidans Seele wurde aus dem Nether gezogen, also gestohlen, und in die Unterwelt gebracht. Sie befindet sich jetzt an einem Ort namens Helheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[45176] = { id = 45176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung der Tapferkeit: Der einstige und zukünftige Herr der Schatten", description = "Die Suche nach dem Körper des Meisters war nicht leicht, aber wir konnten ihn in der Nachtfestung von Suramar ausfindig machen. Laut unser Geheiminformationen nimmt Gul'dan letzte Vorbereitungen am Nachtbrunnen vor, um seine Macht dazu zu verwenden, Sargeras' Seele in Illidans Körper zu übertragen.\n\nDas können wir nur verhindern, wenn wir Illidans eigene unsterbliche Seele wieder in seinen Körper einsetzen.\n\nNehmt das Seelenprisma der Illidari und begebt Euch nach Helheim. Bezwingt Helya und wendet das Prisma auf Illidans Seele an! Übertragt sie zurück in das Herz des Lichts.", sourceObjective = "Bezwingt Helya in der Prüfung der Tapferkeit und verwendet dann das Seelenprisma der Illidari, um Illidans Seele einzufangen.", completion = "<Das Herz des Lichts leuchtet hell auf und absorbiert offenbar das Seelenprisma.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45177] = { id = 45177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung", description = "Illidans Seele ist gut im Herz des Lichts verwahrt. Liefert das Behältnis zusammen mit folgenden Anleitungen an Khadgar aus:\n\nWenn Gul'dan versucht, den Himmel aufzureißen und den Dunklen Titanen in unsere Welt zu bringen, beschwört Ihr die Macht dieses Behältnisses und entlasst Illidans Seele in seinen Körper.\n\nUnd jetzt geht, {name}. Wir haben nicht viel Zeit. Das dunkle Ritual wird bald beginnen.", sourceObjective = "Bringt das Herz des Lichts zu Khadgar in der Violetten Zitadelle in Dalaran.", completion = "Ich... Ich werde mein Bestes geben, Erzdruide. Und Ihr... werdet natürlich den schwierigen Teil übernehmen und den Angriff auf die Nachtfestung anführen müssen!\n\nFÜR AZEROTH!", sourceObjectiveStatus = "unverified-source-field" }
quests[45178] = { id = 45178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchungseindämmung" }
quests[45179] = { id = 45179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Publikumsliebling", description = "Dieser Brief ist eine Einladung, an einer der größten Veranstaltungen in der Geschichte von Azeroth zu teilzunehmen. Es geht um die Kämpfe in der großen Arena, in der die Kontrahenten um Ruhm und Ehre streiten und niemand ihre Namen je vergisst. Oder zumindest nicht bis zur nächsten Saison.", sourceObjective = "Kämpft und siegt in der Arena.", completion = "Glückwünsche sind angebracht, wie ich höre?", sourceObjectiveStatus = "unverified-source-field" }
quests[45180] = { id = 45180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Insel des Kriegs", description = "Eure Champions kehren müde und verwundet zurück. Sie haben ein Banner dabei, das, als Ihr es in den Händen haltet, eine düstere Vorahnung in Euch auslöst, aber zugleich eine Welle der Kriegslust. Sie berichten Euch von einer Insel namens Ashran, auf der Helden unentwegt Krieg führen. Das Kriegsglück neigt sich mal zu einer, mal zur anderen Seite, von denen beide mal Täuschungen ausarbeiten und mal nach vorn drängen, immer in dem Versuch, die Oberhand zu erringen.\n\nAshran braucht Eure Hilfe. Werdet Ihr dem Ruf folgen?", sourceObjective = "Schließt die Quests auf Ashran ab.", completion = "Ashran ist kein Ort für schwache Nerven. Ihr habt Euch wacker geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45181] = { id = 45181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Repeated - Battleground - Tracking Quest" }
quests[45182] = { id = 45182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost: Der zwistige Zwilling", description = "Ein alter Freund von mir, Karam Magusspeer, hat mich bei der Suche nach seinem Bruder Raest um Hilfe gebeten. Karam befürchtet, dass Raest sich mit dunklen Mächten eingelassen hat, und will ihn aufhalten.\n\nRaest wurde einst bei den Kirin Tor ausgebildet, aber er war so versessen auf Macht, dass er sich den verbotenen Künsten der Totenbeschwörung zuwandte. Als man dies entdeckte, wurde er aus unserem Orden verbannt.\n\nSucht Karam im Zauberkasten auf und bietet ihm Eure Hilfe an.", sourceObjective = "Sucht Karam Magusspeer im Zauberkasten in Dalaran auf.", completion = "Ihr kommt von den Kirin Tor? Dann wollt Ihr mir also helfen, meinen Bruder zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[45183] = { id = 45183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Repeated - Ashran - Tracking Quest" }
quests[45184] = { id = 45184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 Class Hall - Special - PVP - PVP Repeated - Arena - Tracking Quest" }
quests[45185] = { id = 45185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft aus den Schatten", description = "Ich weiß, dass mein Bruder in der Vergangenheit oft fehlgeleitet war, aber jetzt fürchte ich, dass er etwas unfassbar Bösem zum Opfer gefallen ist. Vor Kurzem hat er begonnen, sich heimlich mit einem dunklen Kult zu treffen, dessen Mitglieder sich unter den Bewohnern von Dalaran verborgen halten.\n\nIch bin hierhergekommen, um ihn von seinem Irrweg abzubringen, aber er wollte nicht auf mich hören. Und jetzt ist er verschwunden.\n\nAls ich Raest zum letzten Mal sah, hielt er sich im Zimmer über uns auf. Ich konnte dort keine Hinweise finden, aber vielleicht habt Ihr ja mehr Glück.", sourceObjective = "Durchsucht den oberen Raum des Zauberkastens nach Hinweisen zum Aufenthaltsort von Raest Magusspeer.", progress = "Habt Ihr etwas gefunden?", completion = "Ein Brief? Von einem der Kultisten?\n\nDas könnt der entscheidende Hinweis sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[45186] = { id = 45186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 023 - Sargeras Tower 001" }
quests[45187] = { id = 45187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Schattenseite", description = "Dann will mein Bruder also irgendein Ritual mit diesen Kultisten durchführen? Das erklärt, warum er plötzlich weg war, aber nicht, wohin er gegangen ist...\n\nMoment! In diesem Brief steht, dass einige dieser Kultisten des \"Netherpakts\" in der Schattenseite auf der Suche nach Reagenzien sind. Wenn wir uns beeilen, können wir sie vielleicht noch finden!", sourceObjective = "Befragt in der Schattenseite den Abschaum der Schattenseite nach weiteren Informationen zum Aufenthaltsort von Raest Magusspeer.", progress = "Irgendwelche Hinweise, {name}?", completion = "Hmm... nicht wirklich aufschlussreich, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[45188] = { id = 45188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit des Rates", description = "Tut mir leid, {name}, aber ich kann mir einfach keinen Reim darauf machen. Rätsel waren noch nie meine Stärke.\n\nWir sollten dieses Kultistenschreiben zum Erzmagier bringen. Vielleicht kann er Licht ins Dunkle bringen.", sourceObjective = "Bringt das Manifest des Netherpakts zu Erzmagier Karlain in der Violetten Zitadelle in Dalaran.", completion = "Was ist das? Ein Kultistenmanifest?\n\nDann wandelt Raest also tatsächlich auf dunklen Pfaden?", sourceObjectiveStatus = "unverified-source-field" }
quests[45189] = { id = 45189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 024 - Fel River Rock" }
quests[45190] = { id = 45190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dünnste Stelle", description = "Obwohl ich noch nie von diesem Kult des \"Netherpakts\" gehört habe, lässt der Inhalt dieses Manifests auf nichts Gutes schließen.\n\nDoch ich habe eine Theorie. Im Schriftstück ist die Rede von einer \"Stelle, wo die Schale am dünnsten ist\". Ich denke, dabei geht es um den Ort, an dem der Schleier zwischen Azeroth und dem Wirbelnden Nether am dünnsten ist: im Grabmal des Sargeras.\n\nJetzt, wo unsere Streitmächte eine sichere Stellung an der Verheerten Küste errichtet haben, werden Raest und seine Kultisten sicher ihre Gelegenheit ergreifen und versuchen, das Grabmal zu erreichen. Ich empfehle Euch, sie aufzuhalten.", sourceObjective = "Trefft Karam Magusspeer am Teufelsdurchbruch an der Verheerten Küste.", completion = "Mein Bruder ist hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[45191] = { id = 45191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 025 - Night Elf Ruins 001" }
quests[45192] = { id = 45192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißende Runen", description = "Mein Bruder und seine Kultisten führen irgendeine Art Ritual am anderen Ende der Höhle durch. Ich wollte sie davon abhalten, aber mein Bruder hat den Weg mit magischen Zauberschutzen blockiert.\n\nWenn Ihr es schafft, an ihnen vorbeizukommen, können wir ihn vielleicht noch rechtzeitig aufhalten!", sourceObjective = "Findet einen Weg, um an den Zauberschutzen im Teufelsdurchbruch vorbeizukommen, und stellt Euch Raest Magusspeer.", progress = "Wir dürfen jetzt nicht zögern!", completion = "Wir sind zu spät, der Riss ist geschlossen!\n\nWir müssen einen anderen Weg finden, um an ihn heranzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45193] = { id = 45193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Schritt hinterher", description = "Raest ist uns offensichtlich entkommen, aber zumindest stellen seine Kultisten keine so große Bedrohung mehr dar.\n\nWir sollten zu den Kirin Tor zurückkehren. Sie können uns sicher helfen, unseren nächsten Schritt zu planen.", sourceObjective = "Kehrt zu Erzmagier Khadgar in der Violetten Zitadelle in Dalaran zurück.", completion = "Raest ist entkommen? Das ist bedauerlich.\n\nAber dennoch bin ich beruhigt, dass die Kultisten des Netherpakts nicht mehr die Straßen von Dalaran unsicher machen. Ich danke Euch dafür.\n\nDie Kirin Tor werden sofort einen Plan ausarbeiten, wie wir Raest im Wirbelnden Nether aufspüren können. Ich werde Euch rufen lassen, wenn wir einen Weg gefunden haben, an ihn heranzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45198] = { id = 45198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 026 - Fallen Fel Tower" }
