quests[45206] = { id = 45206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overloaded Soulshard" }
quests[45207] = { id = 45207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrling der Nachtgeborenen", description = "Ich würde Euch liebend gerne meinem neuen Lehrling vorstellen, sofern es Euch nicht stört, ein Stückchen zu reisen. Sie ist gerade unterwegs und beobachtet die Enklave der teufelsgeborenen Widerstandskämpfer, die der Legion die Treue geschworen haben.\n\nAls erste Nachtgeborene in der Tirisgarde ist sie sicher darauf erpicht, ihre Fertigkeiten unter Beweis zu stellen!", sourceObjective = "Trefft Arkanistin Ryanna im Purpurdickicht.", completion = "Ich habe schon so viel von Euch gehört, Erzmagier {name}. Es freut mich sehr, Euch endlich zu treffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45208] = { id = 45208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45209] = { id = 45209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehende Augen", description = "Bis vor Kurzem hat uns Ly'leth aus der Nachtfestung magische Nachrichten geschickt. Sie hat darauf geachtet, diese Nachrichten gut zu verbergen... Nur die wachsamsten Seher hätten sie entdecken können.\n\nIm Palast können sie nicht sein... zu viele Interferenzen vom Nachtbrunnen...\n\nNatürlich! Die Terrasse der Erleuchtung! Die Dämmerwache muss dort einen Horchposten eingerichtet haben.\n\nUntersucht die Seherkugeln nach Spuren von Ly'leths Nachrichten. Wir müssen herausfinden, was sie uns mitzuteilen versucht hat!", sourceObjective = "Untersucht 4 Seherkugeln der Dämmerwache auf der Terrasse der Erleuchtung.", progress = "Diese Seherkugeln sind einfach zu verwenden. Berührt sie einfach, um die gespeicherte Nachricht freizugeben.", completion = "Also haben sie tatsächlich ihre Nachrichten abgefangen! Ich hoffe, Ly'leth geht es gut...\n\nWir müssen diese Bresche, von der sie gesprochen hat, sofort untersuchen!", sourceObjectiveStatus = "unverified-source-field" }
