quests[45237] = { id = 45237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45238] = { id = 45238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Kubischer Anziehungspunkt", description = "Verflucht! Das uralte Mana scheint nicht zu funktionieren. Ich muss über das Problem nachdenken, mich nur ein wenig konzentrieren und...\n\nMoment, das ist es! Konzentrieren! Wir müssen die Energie des uralten Manas konzentrieren, um den Würfel zu aktivieren!\n\nIch hörte von einem Manawyrm in Karazhan, der seine Energien fokussieren kann. Das ist vielleicht genau, was wir brauchen!\n\nPasst aber auf, denn dieser Wyrm soll angeblich riesig sein!", sourceObjective = "Besorgt einen Manafokus vom Manaschlinger in Karazhan.", completion = "Ihr habt es geschafft! War der Wyrm wirklich so gigantisch? Ach, egal, Größe ist ja relativ...\n\nLasst uns diesen Fokus in den Würfel einsetzen und mal sehen, was er bewirkt!", sourceObjectiveStatus = "unverified-source-field" }
quests[45239] = { id = 45239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kubische Verschmelzung", description = "Es funktioniert! Der Würfel ist wiederhergestellt! Ich möchte unbedingt herausfinden, was er bewirkt!\n\nDa Ihr all die Laufarbeit erledigt habt, sollte Euch die Ehre gebühren, ihn zu aktivieren. Wollt Ihr es probieren?", sourceObjective = "Aktiviert den mysteriösen Würfel.", completion = "<Die Kraft, die durch den Würfel fließt, drängt Euch, ihn an Euch zu nehmen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45240] = { id = 45240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen treffen", description = "<Todesgebieter/Todesgebieterin>, wir haben ein Erbstück von großer Bedeutung und Macht entdeckt. Raufangs Geschirr ist in der Eiskronenzitadelle aufgetaucht. Wir müssen seiner habhaft werden und dürfen es nicht in die Hände anderer fallen lassen.\n\nIch nehme an, Ihr würdet das Geschirr gerne persönlich beschaffen? Wir haben eine von uns vorausgeschickt, Minerva Rabenkummer, damit sie sich umsieht. Ihr habt sie bereits kennengelernt, nicht wahr? Sie hat uns zutiefst beeindruckt und wir glauben, dass sie unter Eurer Anleitung sehr mächtig werden könnte.\n\nIch werde ein schwarzes Tor für Euch öffnen. Es ist das Beste, wenn Ihr sie dort trefft.", sourceObjective = "Geht durch das Schwarze Tor in der Nähe von Hochlord Darion Mograine und trefft dann Minerva Rabenkummer.", completion = "Todesgebieter! Die Vrykul haben das Geschirr!", sourceObjectiveStatus = "unverified-source-field" }
quests[45243] = { id = 45243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Daumyrs Schwingen", sourceObjective = "Begebt Euch auf Daumyr zur Verheerten Küste.", completion = "Zeigen wir der Legion, was wahre Macht bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[45244] = { id = 45244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 031 - Cave Underneath Horde Ship" }
