quests[45250] = { id = 45250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 035 - Dead Tree" }
quests[45251] = { id = 45251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redundanz", description = "Ein Konstruktvorläufer? Welch kreative Lösung für unser Problem!\n\nWir könnten jetzt möglicherweise Kathra'natirs Macht kanalisieren, ohne ihn freizulassen, aber ich möchte noch eine weitere Schutzmaßnahme hinzufügen, bevor wir es versuchen... sicherheitshalber. Es soll mich niemand der Hinterlist bezichtigen können!\n\nTrefft mich an der Verheerten Küste, wenn Ihr bereit seid!", sourceObjective = "Sucht Aethas an der Verheerten Küste auf.", completion = "Machen wir uns an die Arbeit, einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[45252] = { id = 45252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 037 - Above Lost Temple" }
