quests[45259] = { id = 45259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 044 - Crashed Alliance Gunship" }
quests[45260] = { id = 45260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tag nach dem anderen", description = "Danke, dass Ihr gekommen seid, <Fremder/Fremde>. Es ist schön, Euch wiederzusehen.\n\nIch habe ein Problem in der Stadt, das Eurer Aufmerksamkeit bedarf, aber zuerst...\n\nLasst uns von Hoffnung reden.\n\n<Thalyssra macht eine Geste in Richtung des Arcan'dor.>\n\nDie Frucht des Arcan'dor kann meine Leute wirklich vom Nachtbrunnen befreien, nur wächst sie nicht gerade schnell. Es wird eine Zeit dauern, dieses Heilmittel an alle zu verteilen.\n\nIch glaube, es ist nur recht, dass Ihr mir helft, die Früchte auszuteilen, sobald sie reif sind. Bitte nehmt diese hier und gebt sie jemandem.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Ich werde Euch erneut bitten, dies zu tun, sobald weitere Früchte reif sind.\n\nJetzt müssen wir erst einmal einige verstörende Neuigkeiten besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45261] = { id = 45261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortsetzen der Heilung", description = "Nach den Ereignissen am Mondsichelforum sind die Flüchtlinge hier begieriger als je zuvor, die Gabe des Arcan'dor zu erhalten und auf ewig vom Nachtbrunnen befreit zu werden.\n\nGlücklicherweise trägt der Baum jetzt weitere Früchte. Erneut bitte ich Euch, uns die Ehre zu erweisen, diese Frucht hier in Shal'Aran zu verteilen.\n\nWenn Ihr fertig seid, diskutieren wir weitere Entwicklungen in der Stadt. Silgryn berichtet, dass Arluelle sich als gute Schülerin erwiesen hat und dass die beiden gute Fortschritte bei der Evakuierung der Bürger machen.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Gut. Richtet Eure Aufmerksamkeit nun auf jene, die immer noch in der Stadt leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[45262] = { id = 45262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht von Ly'leth", description = "Der Arcan'dor trägt wieder Früchte. Gerade zur rechten Zeit... Ly'leth hat uns eine Nachricht geschickt, und es scheint, dass sie einen Hinweis auf Vanthir hat. Es ist lange überfällig, dass er diese Gabe erhält... wenn wir es überhaupt schaffen, ihn zu finden.\n\nGebt einem anderen Bürger hier in Shal'Aran eine Frucht. Ich werde derweil Ly'leths Nachricht zu Ende entschlüsseln.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "So. Ich hoffe doch, Ly'leth hat gute Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45263] = { id = 45263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzehr vor der Versammlung", description = "Dass Vanthir da ist, hat viel zur Stimmung der Leute hier beigetragen. Ich darf wohl sagen, dass einige sogar angefangen haben, ihre neu gewonnene Freiheit zu genießen, auch wenn sie ihre geliebte Stadt doch vermissen.\n\nIch werde nicht ruhen, bis ich sie ihnen zurückgeben kann.\n\nUns beiden steht ein wichtiges Treffen bevor. Lasst uns noch mehr Früchte des Arcan'dor verteilen, bevor wir gehen.\n\nIch möchte, dass die Leute wissen, dass ich sie nicht im Stich lasse, auch wenn ich sie vorerst verlassen muss.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Nun gut, gehen wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[45264] = { id = 45264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 045 - South Peak" }
quests[45265] = { id = 45265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rebellion nähren", description = "Jeden Tag fliehen mehr Nachtgeborene aus Suramar, um sich unserer Sache anzuschließen.\n\nUnsere Ränge füllen sich, und mit der Hilfe von großen Helden wie Euch und den Armeen der Horde und der Allianz waren unsere Chancen niemals besser.\n\nHelft mir, mehr Früchte des Arcan'dor zu verteilen. Jede einzelne steht für ein Leben, frei von der sklavischen Abhängigkeit vom Nachtbrunnen!\n\nDanach sprechen wir darüber, wie wir unsere neuen Verbündeten am besten bei ihrer Belagerung unterstützen können.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Gut. Kümmern wir uns jetzt um unsere Geschäfte an der Kriegsfront.", sourceObjectiveStatus = "unverified-source-field" }
quests[45266] = { id = 45266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Front", description = "Unsere Rebellenkämpfer wurden bewaffnet, und die Moral ist gut. Sogar die Elfen der Allianz und der Horde haben ihre Zankereien eingestellt.\n\nWir sind fast bereit, auf die Stadt zu marschieren.\n\nVerteilt die Frucht dieser Woche, dann können wir mit den Vorbereitungen beginnen.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Die Zeit ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45267] = { id = 45267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor der Belagerung", description = "So viele Jahre meines Lebens habe ich mit dem Studium in der Nachtfestung verbracht...\n\nNiemals hätte ich gedacht, dass ich mir eines Tages einen Weg hinein würde erkämpfen müssen.\n\nDie Zeit ist knapp. Der Kampf steht uns schon bald bevor.\n\nSetzt bitte unsere Tradition fort und nährt einen weiteren Flüchtling mit der Frucht des Arcan'dor.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Gerade zur rechten Zeit. Wir sind bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[45268] = { id = 45268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beraterin und die Arkanistin", description = "Diese neue Erste Arkanistin, die Elisande ernannt hat... diese... Andaris. Wenn sie so gefährlich ist, wie ich gehört habe, dann könnte Ly'leth schon verloren sein.\n\nEs tut mir leid, ich sollte nicht solchen Gedanken nachhängen. Es ist nur so, dass wir eine besorgniserregende Nachricht erhalten haben.\n\nHelft mir, die letzten Früchte des Arcan'dor zu verteilen, danach werden wir über die Nachricht sprechen.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Ich bin froh, dass wir mein Volk immer noch heilen können, aber... ich habe schlechte Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45269] = { id = 45269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmack von Freiheit", description = "Wir sind so bereit, wie wir je sein können. Sobald wir Valtrois' Plan umsetzen, können wir das Sanktum der Ordnung angreifen und Andaris ein Ende bereiten. Sie wird niemals erwarten, dass wir unsere Verdorrten auf Teufelsmagie vorbereitet haben, und ihre Überheblichkeit wird ihr Untergang sein.\n\nKommt, lasst uns die Leute ein letztes Mal nähren.", sourceObjective = "Gebt die Frucht des Arcan'dor einem Flüchtling aus Suramar in Shal'Aran.", completion = "Nun gut. Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45270] = { id = 45270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 046 - Bundle of Cages 000" }
quests[45271] = { id = 45271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand", description = "Die Erste Arkanistin Thalyssra hat schlechte Nachrichten bezüglich der Rebellion der Nachtsüchtigen erhalten und benötigt Eure Unterstützung.\n\nReist nach Shal'Aran in Suramar und trefft Euch mit ihr.", sourceObjective = "Sprecht mit der Ersten Arkanistin Thalyssra in Shal'Aran.", completion = "Willkommen. Ihr hättet zu keinem besseren Zeitpunkt hier ankommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[45272] = { id = 45272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: Vermisstenmeldung", description = "Die Erste Arkanistin Thalyssra hat um Eure Hilfe bei der Suche nach ihren vermissten Leuten gebeten.\n\nSie hat von einem sehr unerwarteten Verbündeten einen Hinweis erhalten.\n\nTrefft Euch mit ihr in Shal'Aran in Suramar.", sourceObjective = "Sprecht mit der Ersten Arkanistin Thalyssra in Shal'Aran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45276] = { id = 45276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 047 - Webbed Path" }
quests[45277] = { id = 45277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revolte: Der Mondsichelaufstand", description = "Die Erste Arkanistin Thalyssra hat eine Nachricht geschickt: Sie hat eine Botschaft von Ly'leth erhalten. Eure Hilfe wird benötigt.\n\nReist nach Shal'Aran in Suramar und helft, so gut Ihr könnt.", sourceObjective = "Sprecht mit der Ersten Arkanistin Thalyssra in Shal'Aran.", completion = "Das werdet Ihr hören wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45278] = { id = 45278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: Ein Elfenproblem", description = "Die Allianz und die Horde sind in Suramar eingetroffen. Die Erste Arkanistin Thalyssra braucht Eure Hilfe, um eine Vorstellung in die Wege zu leiten.\n\nTrefft Euch mit Thalyssra in Shal'Aran.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Shal'Aran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45279] = { id = 45279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 048 - Western Island Tree" }
quests[45280] = { id = 45280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: Rüsten für den Krieg", description = "Flüchtlinge strömen nach Shal'Aran, und viele sind willens, für Thalyssras Rebellenarmee zu kämpfen.\n\nSie brauchen Waffen, Ausbildung und Hilfe von jedem, der sie zur Verfügung stellen kann.\n\nGeht nach Shal'Aran und bietet Eure Unterstützung an.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Shal'Aran.", completion = "Dieses Problem kam unerwartet, aber wir haben mehr Soldaten als Nahrung oder Waffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45281] = { id = 45281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: Marsch auf Suramar", description = "Die Erste Arkanistin Thalyssra hat eine Nachricht geschickt: Die Zeit ist reif, mit unserem Angriff auf Suramar zu beginnen. Die Elfenarmeen der Horde, der Allianz, der Kirin Tor und der Nachtsüchtigen sind versammelt.\n\nSie warten nur auf Eure Ankunft, um den Angriff zu starten.\n\nMeldet Euch in Shal'Aran. Trefft Euch mit der Ersten Arkanistin Thalyssra und bereitet Euch auf die Schlacht vor.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Shal'Aran.", completion = "Die Zeit für unseren Angriff ist gekommen. Es ist nun an der Zeit, Suramar von Elisande und ihren dämonischen Verbündeten zurückzuerobern!", sourceObjectiveStatus = "unverified-source-field" }
quests[45282] = { id = 45282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: Elisandes Antwort", description = "Die vereinten Streitkräfte der Elfen stehen bereit, um mit der Belagerung der Tore der Nachtfestung zu beginnen.\n\nMeldet Euch bei der Ersten Arkanistin Thalyssra in Shal'Aran, um die Belagerung zu starten.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Shal'Aran.", completion = "Die Zeit für unseren Angriff ist gekommen. Es ist nun an der Zeit, Suramar von Elisande und ihren dämonischen Verbündeten zurückzuerobern!", sourceObjectiveStatus = "unverified-source-field" }
quests[45283] = { id = 45283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 049 - Behind Purple Ritual" }
quests[45284] = { id = 45284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 050 - Spikes Over Green" }
quests[45285] = { id = 45285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: So stark wie unser Wille", description = "Nach dem Angriff von Elisande ist die Notwendigkeit, die Ränge der Rebellion der Nachtsüchtigen zu stärken, dringender denn je.\n\nEs werden gerade Pläne umgesetzt, die dies auf unkonventionelle Weise erreichen könnten.\n\nMeldet Euch bei der Ersten Arkanistin Thalyssra in Shal'Aran, um mehr Details zu erfahren.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Shal'Aran.", sourceObjectiveStatus = "unverified-source-field" }
quests[45286] = { id = 45286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 051 - Death Knight Overhang" }
quests[45287] = { id = 45287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand: Erstürmung der Nachtfestung", description = "Die Erste Arkanistin Thalyssra hat die Nachricht geschickt, dass ihre Streitkräfte bereit sind. Es ist Zeit für Euch, den Angriff gegen die Nachtfestung anzuführen.\n\nMeldet Euch in Shal'Aran in Suramar, um Details zu erfahren.", sourceObjective = "Trefft Euch mit der Ersten Arkanistin Thalyssra in Shal'Aran.", completion = "Die Zeit für unseren Angriff ist gekommen. Es ist nun an der Zeit, Suramar von Elisande und ihren dämonischen Verbündeten zurückzuerobern!", sourceObjectiveStatus = "unverified-source-field" }
quests[45288] = { id = 45288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 052 - Green Ritual Chamber" }
quests[45289] = { id = 45289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 053 - Underneath Tomb Bridge" }
quests[45291] = { id = 45291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Bücherwyrms", description = "Dank meiner körperlosen Gestalt konnte ich den Turm zum ersten Mal ohne Sorge um meine Sicherheit betreten. Und dort herrscht ein ziemliches Chaos!\n\nIch könnte ein wenig Hilfe bei den Aufräumarbeiten gebrauchen. Wir sollten in der Bibliothek anfangen. Diese ganzen staubigen Folianten ziehen Manawyrms an!\n\nBitte sammelt alle Bücher auf, die auf den Boden gefallen sind. Und solltet Ihr Manawyrms entdecken, die daran knabbern, dann tretet sie platt!", sourceObjective = "Räumt die Bibliothek von Karazhan auf.", completion = "WIE klein wart Ihr? Du meine Güte! Das muss die Sache komplizierter gemacht haben.\n\nEs scheinen mehr Bücher auf dem Boden zu liegen als zu Beginn unserer Arbeit. Als würden die Bücher von selbst aus den Regalen springen...\n\nDas wird schwieriger, als ich gedacht habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[45292] = { id = 45292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Neustart des Aufräumers", description = "Der Wächter Medivh hatte den Kurator erschaffen, um über Karazhan zu wachen. Aber ich fürchte, dass diese Einheit außer Kontrolle ist. Ist das Modell zu lange in Betrieb, kann das zu Fehlfunktionen führen.\n\nBitte begebt Euch hoch in die Menagerie und schaltet den Kurator aus. Bitte durchsucht außerdem den Bereich nach einer Kiste mit übriggebliebenen Motivationskristallen und kehrt damit zu mir zurück.\n\nSelbst mit meinen Grundkenntnissen sollte ich in der Lage sein, den Motivator zu ersetzen. Dann wird uns der Kurator dabei helfen, im Turm aufzuräumen.", sourceObjective = "Deaktiviert den Kurator und sucht nach der Kiste mit übriggebliebenen Motivationskristallen.", progress = "Habt Ihr die Ersatzteilkiste gefunden?", completion = "Die Kiste ist leer? Verflucht!\n\nIch bin zwar Magier, aber Medivhs Motivationskristallzauber sind eine Nummer zu groß für mich!", sourceObjectiveStatus = "unverified-source-field" }
quests[45293] = { id = 45293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Heiße Eisen", description = "Bis jetzt sind meine Aufräumarbeiten in Karazhan kein rauschender Erfolg. Uns fehlt einfach das Glück.\n\nGlück wie... Ah, genau, Hufeisen! Außerhalb des Turms ist eine Kiste Hufeisen zurückgelassen worden. Es wollte sie niemand reinbringen, weil die Sterblichkeitsrate ja so hoch war...\n\nKönntet Ihr bitte die Kiste zu Koren in den Ställen bringen? Aber passt auf Attumen auf. Der Jäger ist Fremden gegenüber nicht sonderlich... gastlich gestimmt.", sourceObjective = "Bringt die Kiste mit \"neuen\" Hufeisen zu Koren dem Schmied in Karazhan.", progress = "Wie ist es gelaufen?", completion = "Oh je! Das war natürlich mein Fehler!\n\nIch hätte mich von dem ordnungsgemäßen Zustand der Hufeisen überzeugen sollen, bevor ich sie Euch ausliefern ließ.\n\nDiese Luftfeuchtigkeit ist wirklich unerträglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[45294] = { id = 45294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Palaver in der Pause", description = "Die neuen Stücke im Opernhaus haben wirklich allen gut gefallen... außer den Ensemblemitgliedern der älteren Vorführungen. Ihr gekränkter Stolz hat die Stimmung äußerst angespannt!\n\nRomulo und Julianne würden sich am liebsten gegenseitig vergiften.\n\nDer depressive Blechkopf weint so viel, dass er schon ganz rostig wird.\n\nRotkäppchen behauptet, ihre Vertretung habe ihr Käppchen gestohlen und sei damit weggelaufen, um lieber Schach zu spielen.\n\nDiese Schauspieler! Aber wir müssen sie bei Laune halten, falls das Publikum sie erneut auf der Bühne sehen will. Bitte helft mir, ihre Nerven zu beruhigen!", sourceObjective = "Helft Darius, die verletzten Egos der alten Ensemblemitglieder zu beruhigen. Treibt eine positive Kritik eines Zuschauers auf, um die Spannungen zwischen Romulo und Julianne zu beruhigen, stehlt ein Rosenbouquet von einem der neuen Stücke, um dem Blechkopf wieder etwas Selbstvertrauen zu geben und findet heraus, wo Rotkäppchens Vertretung ihr Käppchen im Schachsaal versteckt hat.", progress = "Wie ist es gelaufen?", completion = "Kaum zu glauben, dass Ihr gefunden habt, was wir brauchen!\n\nAlso, ich hatte ja keine Zweifel, aber... das ist das erste Mal, dass eines meiner Projekte tatsächlich funktioniert.\n\nAuf jeden Fall sollten wir die Schauspieler etwas beruhigen können, wenn wir diese Dinge ausliefern.\n\nEin wahrhaft glorreicher Tag!", sourceObjectiveStatus = "unverified-source-field" }
quests[45295] = { id = 45295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Schluss mit der Spinnerei", description = "Ich gebe es ja zu... Selbst als Geist habe ich noch panische Angst vor Spinnen. Diese vielen Beine! Diese Fangzähne! Klebrige Netze, die aus ihren...\n\n<Darius führt ein windet sich so angewidert, dass man es kaum mitansehen mag.>\n\nAber ich gehe davon aus, dass Weltenretter wie Ihr keine Probleme damit haben. Und das ist umso besser, weil eine ganze Brut von ihnen die Bedienstetenunterkünfte überrannt hat.\n\nIhr werdet Euch doch darum kümmern, oder? Wenn Ihr sie nämlich nicht alle erwischt, vermehren sie sich wieder.", sourceObjective = "Tötet die Spinnen in den Bedienstetenunterkünften.", completion = "Ihr habt doch alle von ihnen erwischt, oder?\n\nAuf jeden Fall streiche ich das jetzt von der Liste. Das brauche ich wohl nicht zu kontrollieren.\n\n<Darius zieht ein angewidertes Gesicht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45296] = { id = 45296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenarbeit", description = "Die verkohlten Knochenfragmente sind immer noch voll von uralter Macht. Darius wäre sicher sehr interessiert daran, sie zu untersuchen und von Eurem Sieg über den Schrecken der Nacht zu hören.", sourceObjective = "Bringt die verkohlten Knochenfragmente zu Darius.", completion = "Der Schrecken der Nacht ist bezwungen! Das ist fantastisch!\n\nViele Jahre sind vergangen seitdem der verderbte Medivh den blauen Drachen Arcanagos getötet hat. Erzmagier Alturus hat die Überreste des gefallenen Drachen ausfindig gemacht, um die Macht des Wächters zu studieren. \n\nIm Nachhinein betrachtet war das vielleicht keine so gute Idee. \n\nAuf jeden Fall war Eure Hilfe von unschätzbarem Wert.\n\nEs gibt viel für mich zu tun beim Aufräumen in Karazhan, aber vorerst werde ich Euch nicht mehr um Hilfe bitten. Danke noch einmal für Euren Einsatz, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[45298] = { id = 45298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 054 - Death Knight Nook" }
