quests[45300] = { id = 45300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 056 - Giant Tree" }
quests[45301] = { id = 45301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Rechten sehen", description = "In Mardum war es monatelang ruhig. Ich frage mich, warum die Legion uns gerade jetzt angreift? Vielleicht ist das ihre Rache dafür, dass wir ihr Schlachtschiff an der Verheerten Küste zerstört haben...\n\nWir sollten besser selbst da runtergehen und uns nützlich machen, oder?", sourceObjective = "Sprecht mit Kyra Lichtklinge und fliegt dann nach Mardum.", completion = "Ihr habt es geschafft. Sehr gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[45302] = { id = 45302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Brawlers Missions - Has Completed Any Brawlers Mission with Overmax - Tracking Quest" }
quests[45303] = { id = 45303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Special - Brawlers - Fight 03 - Tracking Quest" }
quests[45304] = { id = 45304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf mit der Finsternis", description = "Eure Champions sind einigermaßen beeindruckt vom Kampf gegen den Schattenmeister zurückgekehrt.", sourceObjective = "Kehrt zur Kampfgilde zurück.", completion = "Sagt's nicht weiter, aber ich bin froh, dass Ihr gewonnen habt. Der Typ hat mir immer Schauer über den Rücken gejagt. Bereit für die finale Herausforderung?", sourceObjectiveStatus = "unverified-source-field" }
