quests[45312] = { id = 45312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischklopsragout", description = "Eure Champions sind mit einem blutigen, zerzausten und ziemlich übel riechenden Haarbüschel zurückgekehrt.", sourceObjective = "Bringt das Haarbüschel zur Kampfgilde.", completion = "Ich kann nicht fassen, dass Ihr ihn besiegt habt! Fleischklops war so beeindruckt, er will unbedingt für Euch arbeiten. Hoffen wir mal, das Ihr das nicht bereut.", sourceObjectiveStatus = "unverified-source-field" }
quests[45313] = { id = 45313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Brawlers - Fight 04 - Overmax Reward Credit - Tracking Quest" }
