quests[45315] = { id = 45315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1.5 Class Hall - Brawlers - Intro - Tracking Quest - Has Picked up Quest Item" }
quests[45316] = { id = 45316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stabilisierung von Suramar", description = "Elisandes Plan ist nach hinten losgegangen. Sie wollte unsere Rebellion ersticken, indem sie am Mondsichelforum ein Exempel statuiert.\n\nStattdessen hat sie die Flamme der Shal'dorei heller entzündet, als ich es je hätte tun können.\n\nWir müssen geschlossen eine Kampagne gegen Elisande und die Legion führen, indem wir sie in jeder Ecke Suramars bekämpfen.\n\nZeigt den Leuten, dass es immer noch Hoffnung gibt... dass es immer noch Helden gibt, die bereit sind, für sie zu kämpfen!", sourceObjective = "Schließt 10 Weltquests in Suramar ab.", completion = "Habt Dank, {name}. Jeden Tag kommen wir der Freiheit für Suramar ein Stückchen näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[45317] = { id = 45317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf an allen Fronten", description = "Wir sind fast bereit, die Tore zu belagern. Eure Mühen hier waren monumental, {name}.\n\nAber lasst uns nicht vergessen, dass Ihr auch <der/die> {class}t seid. Eure Streitkräfte verlassen sich auf Eure Befehle. Als Einzelperson hat niemand der Legion etwas entgegenzusetzen.\n\nSetzt Euren Dienst fort. Wenn alle Mitglieder Eures Ordens auf Azeroth Euch folgen, ist uns der Sieg sicher.", sourceObjective = "Schließt 5 Missionen Eurer Ordenshalle ab.", completion = "Führung ist eine schwere Bürde, {name}.\n\nOft müssen wir unsere Aufmerksamkeit teilen. Achtet darauf, nie den Überblick zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[45318] = { id = 45318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
