quests[45328] = { id = 45328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45329] = { id = 45329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Portale", description = "Das ist eine ernst zu nehmende Invasion, aber kein Problem für <einen Rächer/eine Rächerin> Eures Kalibers. Es wird Zeit, Eure Waffen sprechen zu lassen!", sourceObjective = "Schließt 3 Legionsportale.", completion = "Das war ja erstaunlich leicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[45330] = { id = 45330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Späher Spuren", description = "Die verschwundenen Späher und vor allem Lady S'theno zu finden, wird keine leichte Aufgabe. Ich vermute, dass sie womöglich gar nicht gefunden werden will.\n\nWir vertrauen auf Euch, {name}!", sourceObjective = "Findet Lady S'theno und 10 Späher der Illidari.", completion = "Ihr habt die meisten unserer Späher lebend retten können... und Lady S'theno wirkt auch deutlich einsichtiger. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[45331] = { id = 45331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Acherus", description = "Ihr seid unglaublich gewachsen, seit wir uns das letzte Mal sahen, {name}. Jetzt, da wir das Geschirr haben, sollten wir sehen, ob Mograine einen Plan hat, um es nutzbringend einzusetzen.", sourceObjective = "Kehrt zu Hochlord Darion Mograine in Acherus zurück.", completion = "Willkommen zurück, Todesgebieter. Wie ich sehe, wart Ihr erfolgreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[45332] = { id = 45332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Zirux" }
quests[45333] = { id = 45333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf unheiligem Boden" }
quests[45337] = { id = 45337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo'arg Brute Squad" }
quests[45339] = { id = 45339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Teufelshammer", description = "Wir müssen SOFORT zurück zur Teufelshammer!", sourceObjective = "Verwendet das Illidaritor, um zur Teufelshammer zurückzukehren.", completion = "Da habt Ihr einen ganz schönen Schlag abbekommen...\n\nIch bin ehrlich gesagt ziemlich überrascht, dass sich die Teufelshammer nicht selbst zerlegt hat, als wir ihre Waffen abgefeuert haben. Wir haben Glück, dass wir noch am Leben sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[45340] = { id = 45340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Giant's Stash" }
quests[45341] = { id = 45341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45342] = { id = 45342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe verabreichen", description = "Leider haben schon viele unserer Verbündeten den Kampf an den teufelsverseuchten Küsten aufgenommen.\n\nSolange sie selbst von der Verseuchung betroffen sind, werden sie den Kampf niemals gewinnen können.\n\nNehmt das Antiserum und verabreicht es Euren Verbündeten, um sie zu heilen.\n\nRoland und ich werden uns hier um die zu Verarztenden kümmern.", sourceObjective = "Verabreicht das Antiserum den Kämpfern der Legionsrichter.", completion = "Eure Verbündeten verdanken Euch ihr Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[45343] = { id = 45343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine merkwürdige Seuche", description = "Mir wurde berichtet, dass eine überaus merkwürdige Seuche eine kleine Küstenregion am Hochberg heimgesucht hat.\n\nDie örtlichen Stämme sind aus Furcht vor Ansteckung mit dieser Krankheit, für die es kein Heilmittel gibt, geflohen.\n\nEine von uns war in dieser Gegend unterwegs und ihr Begleiter ist nun erkrankt. Sie hat die Konklave um Hilfe gebeten. Sucht sie auf, <Hohepriester/Hohepriesterin>, und tut alles, was in Eurer Macht steht, um diese Seuche aufzuhalten.", sourceObjective = "Findet Aelthalyste am Hochberg.", completion = "Ah, sehr gut. Dann hat die Konklave also meinen Hilferuf erhalten. Aber ich hätte nicht gedacht, dass sie gleich ihren Anführer schicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[45344] = { id = 45344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proben von der Quelle", description = "Wie Ihr seht, ist mein Gefährte schwer erkrankt.\n\nEr muss sich das Gleiche eingefangen haben wie diese Tauren. Das ganze Lager wurde ausgelöscht!\n\nDie Krankheit scheint teuflischen Ursprungs zu sein und auf keine bekannten Heilmittel anzusprechen.\n\nIch arbeite unermüdlich daran, ein Heilmittel zu finden, aber Roland hier bleibt nicht mehr viel Zeit.\n\nEs würde mir sehr helfen, wenn mir jemand Proben direkt von der Quelle bringen könnte.\n\nAber vermeidet unbedingt den direkten Kontakt mit der Seuche. Es könnte hilfreich sein, dabei zu levitieren.", sourceObjective = "Sammelt kontaminierte Proben aus den Ansammlungen gasiger Teufelsenergie an der Westküste des Hochbergs.", progress = "Habt Ihr die Proben einsammeln können?", completion = "Ich hoffe, Ihr wart vorsichtig beim Einsammeln der Proben, {name}. Ich würde es mir kaum verzeihen können, wenn ich für die Erkrankung des Hohepriesters verantwortlich wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[45345] = { id = 45345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schelmische Waldgeister", description = "Es ist ein gut gehütetes Geheimnis, dass der Staub, den die Waldgeister für ihre diversen Tricks verwenden, regenerierende Eigenschaften hat.\n\nEinige Mitglieder der Alchemistenzunft sperren sich gegen diese Behauptung, aber sie weisen sie nur deshalb zurück, weil sie es nie geschafft haben, diese seltene Zutat zu beschaffen.\n\nWaldgeister hüllen sich oft in Illusionen, um der Entdeckung zu entgehen.\n\nDie Ziegen hier sind von einem seltsamen Schimmer umhüllt, der darauf hindeutet, dass es sich um verkleidete Waldgeister handeln könnte.\n\nBannt die Magie, mit der sie sich umgeben haben, um ihre wahre Form zu enthüllen.", sourceObjective = "Wendet 'Magiebannung' auf Hügelschreiter der Rußhufe an, um schelmische Waldgeister zu entlarven, und sammelt ihren schillernden Staub ein.", progress = "Habt Ihr den schillernden Staub schon gefunden, den ich so dringend benötige?", completion = "Ich danke Euch, {name}. Ich dachte mir doch, dass diese Ziegen etwas merkwürdig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[45346] = { id = 45346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torkelnde Tote", description = "Diese Seuche von teuflischer Verderbnis scheint in drei Stufen zu verlaufen.\n\nZunächst tritt ein zäher, schleimiger Husten auf.\n\nAnschließend nimmt die Haut einen kränklich-grünen Farbton an.\n\nUnd dann erfolgt die vollständige Transformation des Opfers in eine wandelnde Leiche. In diesem Zustand können wir den Opfern wohl die meisten Informationen über die Krankheit entlocken.\n\nIch habe ein Behältnis, um sie sicher zu verwahren, aber vor dem Einsammeln müssen sie gefesselt werden.", sourceObjective = "Wendet 'Untote fesseln' auf die torkelnden Leichen an, damit sie mit dem Leichensammler eingesammelt werden können.", completion = "Man kann die Opfer auf Stufe III zwar nicht heilen, aber zumindest können sie uns wertvolle Hinweise zum Verlauf dieser Seuche liefern.", sourceObjectiveStatus = "unverified-source-field" }
quests[45347] = { id = 45347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilmittelherstellung", description = "Mit dem, was Ihr mir gebracht habt, habe ich ein hoffentlich wirksames Heilmittel hergestellt. Jetzt fehlt nur noch etwas mächtige Magie, mit der Ihr es hoffentlich versehen könnt.\n\nDas Heilmittel befindet sich dort auf dem Alchemietisch.\n\nBitte beeilt Euch, {name}. Roland wird von Minute zu Minute schwächer.", sourceObjective = "Verseht das ungetestete Heilmittel mit Magie, bevor Ihr es Roland Abernathy verabreicht.", progress = "Ich werde alles tun, was in meiner Macht steht, um ein Heilmittel gegen diese Verseuchung zu finden.", completion = "Ausgezeichnete Arbeit, {name}. Einen Moment lang dachte ich schon, ich müsste mir einen neuen Gefährten suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45348] = { id = 45348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Verwahrung", description = "Wie es scheint, stellt das empfindliche Gleichgewicht zwischen heiliger und Schattenmagie den Schlüssel zur Heilung dieser Seuche dar. Offensichtlich muss noch etwas an dem Heilmittel gearbeitet werden, um unerwünschte Nebenwirkungen wie den Tod zu minimieren.\n\nIn der Zwischenzeit könntet Ihr das Antiserum zurück in die Sicherheit des Netherlichttempels bringen. Ich werde solange unermüdlich daran arbeiten, die Quelle der Seuche aufzudecken.", sourceObjective = "Bringt das Antiserum zu Alonsus Faol im Netherlichttempel.", progress = "Was haben wir denn hier?", completion = "Dieses Heilmittel kommt genau zur rechten Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[45349] = { id = 45349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Verheerten Küste", description = "Wir haben Nachrichten von den Kämpfenden an der Verheerten Küste erhalten. Der Ursprung der Seuche scheint sich auf einer bestimmten Insel vor der Westküste zu befinden.\n\nEs haben sich schon viele unserer Verbündeten infiziert. Wir müssen schnell handeln, um zu verhindern, dass sich die Seuche weiter ausbreitet.", sourceObjective = "Begebt Euch zur Verheerten Küste.", completion = "Ihr seid da, Hohepriester! Schnell! Wir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45350] = { id = 45350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf gegen die Seuche", description = "Ich habe den Ursprung der Seuche an dieser Küste ausfindig machen können. Die Brennende Legion verwendet Teufelskondensatoren, um den Boden mit einem Teppich aus teuflischer Verderbnis zu überziehen. Wer sie berührt, erkrankt auf der Stelle.\n\nSchaltet Ozzuk den Verderber und seine Teufelskondensatoren aus, damit sich die Seuche nicht weiter ausbreitet.", sourceObjective = "Bekämpft die Seuche, indem Ihr Ozzuk den Verderber und seine Teufelskondensatoren vernichtet.", completion = "Ich glaube, dank unserer gemeinsamen Anstrengungen konnten wir die teuflische Verderbnis in Azeroth ausmerzen.\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[45351] = { id = 45351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overloaded Soulshard" }
quests[45352] = { id = 45352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Titanen berührt", description = "Meine Güte! Ihr habt es geschafft, Euch einen legendären Gegenstand für Eure nächsten Abenteuer zu beschaffen. Ich hatte schon lange die Theorie, dass solche Gegenstände ihre Macht direkt von den Titanen beziehen. Das hier könnte sich als Gelegenheit erweisen, diese Spekulationen einem Test zu unterziehen!\n\nEs heißt, dass der Nachtbrunnen seine Macht aus dem Auge von Aman'thul bezieht. Ich glaube, dass die Macht der Titanen nun nach Jahrhunderten in unmittelbarer Nähe den Bewohnern der Nachtfestung innewohnt. Bringt mir Überreste dieser Energie, dann werde ich Eure Ausrüstung mit Macht erfüllen.", sourceObjective = "Bringt 50 Essenzen von Aman'thul zu Arkanomant Vridiel.", progress = "Aman'thul wurde wahrscheinlich schon vor zahllosen Äonen getötet, und doch ist seine Macht noch nicht versiegt. Wie ist das möglich?", completion = "Wunderbar! Es ist solch eine Freude, mit so großartiger Handwerkskunst arbeiten zu dürfen. Kommt bitte wieder, wenn Ihr noch so ein Meisterstück finden solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[45353] = { id = 45353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Titanen berührt", description = "Die Stärke der Titanen könnte das Einzige sein, was es uns ermöglicht, die Brennende Legion zurückzudrängen. Verschafft mir mehr dieser Stärke. Das wird unsere Chancen verbessern, Gul'dan zu besiegen.", sourceObjective = "Bringt 50 Essenzen von Aman'thul zu Arkanomant Vridiel.", progress = "Aman'thul wurde wahrscheinlich schon vor zahllosen Äonen getötet, und doch ist seine Macht noch nicht versiegt. Wie ist das möglich?", completion = "Ich schätze mich glücklich, mit den Helden arbeiten zu können, die für das Überleben unserer Welt kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45354] = { id = 45354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Balance der Scheiben", description = "Diese Scheiben strahlen eine unglaubliche Kraft ab! Das muss an ihrer Nähe zueinander liegen. Wir müssen sie von hier wegbringen, bevor die Resonanz noch weiter zunimmt und eine Katastrophe in diesen heiligen Hallen auslöst.\n\nIch werde sie an einen Ort schicken, wo wir ihre Energie beherrschen und eine Explosion vermeiden können: zum Auge der Ewigkeit.\n\nDort können wir zu Ende bringen, was Antonidas nicht gelungen ist. Sprecht mich wieder an, wenn Ihr zum Aufbruch bereit seid.", sourceObjective = "Schließt die Prüfung zur Ableitung der überschüssigen Energie aus den Scheibenfragmenten ab.", completion = "Zu behaupten, dass Ihr Euch Euren Status als Erzmagier verdient hättet, wäre eine Untertreibung. Euer heutiger Erfolg beweist, dass Ihr dazu geboren wurdet.\n\nJetzt besteigt Euer neues Transportmittel und werft Euch der Legion mit der ganzen Macht Eures Wissens entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45358] = { id = 45358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmungsmaßnahmen" }
quests[45365] = { id = 45365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Wand of Simulated Life" }
quests[45368] = { id = 45368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Shard" }
quests[45372] = { id = 45372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Nachtgeborenen", description = "Kurz nach Eurer ruhmreichen Rückkehr von der Nachtfestung musste Thalyssra aufgrund dringender Angelegenheiten in den Palast zurückkehren.\n\nSie bittet Euch, zu ihr zu kommen.\n\nSprecht mich an, wenn Ihr bereit seid, sie aufzusuchen.", sourceObjective = "Sprecht mit Oculeth und trefft Thalyssra in der Nachtfestung.", completion = "Danke, dass Ihr gekommen seid, {name}.\n\nFrüher oder später müssen die Nachtgeborenen ihr Schicksal in die eigenen Hände nehmen, ungeachtet der Hilfe von Fremden wie Euch.\n\nEs ist keine einfache Aufgabe, aber Elisande hat uns gezeigt, dass wir allein und ohne den Nachtbrunnen zurechtkommen müssen, wenn wir wieder Teil der Welt sein wollen.\n\nIch danke Euch für alles, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45379] = { id = 45379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzmeister Iks'reeged", sourceObjective = "Tötet 1 Verschlinger der Teufelsschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45381] = { id = 45381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Talisman der Shal'dorei", description = "Als die Nachtfestung gebaut wurde, haben meine Leute einen Talisman erschaffen, der Zugang zu diesen Hallen gewährt. Dank der Macht des Talismans kann man ungehindert durch die Hallen streifen und die Magistrix direkt angreifen. Mithilfe der Fragmente der Kraft des Nachtbrunnens könnten wir den Talisman orten und diesen törichten Krieg beenden...", sourceObjective = "Sammelt 4 Echos der Zeit von Elisande in der Nachtfestung auf dem Schwierigkeitsgrad 'Normal' ein.", progress = "Ohne den Talisman müssen wir uns mitten durch die Stadt kämpfen.", completion = "Die Kraft dieser Fragmente wird mir ermöglichen, den Talisman zu uns zu rufen! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[45382] = { id = 45382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Talisman der Shal'dorei", description = "Als die Nachtfestung gebaut wurde, haben meine Leute einen Talisman erschaffen, der Zugang zu diesen Hallen gewährt. Dank der Macht des Talismans kann man ungehindert durch die Hallen streifen und die Magistrix direkt angreifen. Mithilfe der Fragmente der Kraft des Nachtbrunnens könnten wir den Talisman orten und diesen törichten Krieg beenden...", sourceObjective = "Sammelt 4 Echos der Zeit von Elisande in der Nachtfestung auf dem Schwierigkeitsgrad 'Heroisch' ein.", progress = "Ohne den Talisman müssen wir uns mitten durch die Stadt kämpfen.", completion = "Die Kraft dieser Fragmente wird mir ermöglichen, den Talisman zu uns zu rufen! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[45383] = { id = 45383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Talisman der Shal'dorei", description = "Als die Nachtfestung gebaut wurde, haben meine Leute einen Talisman erschaffen, der Zugang zu diesen Hallen gewährt. Dank der Macht des Talismans kann man ungehindert durch die Hallen streifen und die Magistrix direkt angreifen. Mithilfe der Fragmente der Kraft des Nachtbrunnens könnten wir den Talisman orten und diesen törichten Krieg beenden...", sourceObjective = "Sammelt 4 Echos der Zeit von Elisande in der Nachtfestung auf dem Schwierigkeitsgrad 'Mythisch' ein.", progress = "Ohne den Talisman müssen wir uns mitten durch die Stadt kämpfen.", completion = "Die Kraft dieser Fragmente wird mir ermöglichen, den Talisman zu uns zu rufen! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[45385] = { id = 45385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen vorbereitet sein!", description = "Die Legionsschiffe sind vorläufig weg. Es ist nur eine Frage der Zeit, bis sie wieder angreifen, und wir müssen vorbereitet sein.\n\nWir müssen umgehend mit den Reparaturen beginnen! Lady S'theno leitet die Suche nach Ersatzteilen. Sie würde alles tun, um festen Boden unter den Füßen zu haben, ha!\n\nSie wartet auf Euch an der Verheerten Küste.", sourceObjective = "Sprecht mit Lady S'theno beim Lager der Illidari an der Verheerten Küste.", completion = "Ess isst soweit, Rächer {name}. Ess wartet Arbeit auf unss.", sourceObjectiveStatus = "unverified-source-field" }
quests[45390] = { id = 45390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen der Vrykul" }
quests[45391] = { id = 45391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lady S'theno", sourceObjective = "Ihr habt keinerlei Mühen gescheut, um unseren Pakt zu würdigen, Rächer {name}. Ihr wissst, dasss ich nichtss für schwülstige Reden übrighabe, aber ich versichere Euch, dasss ich dankbar bin.\n\nWenn Ihr wünscht, werde ich meinen Platz an Eurer Sseite einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45392] = { id = 45392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Andenken", description = "Diese Blumen waren... eine schöne Geste.\n\n<Velonara schnuppert an einer der schwarzen Rosen.>\n\nIch habe noch eine Kapuze. Sie ist nichts Besonderes, aber vielleicht möchte Moorgoth sie dennoch haben.\n\nAber er soll sich keine allzu großen Hoffnungen machen. Ich will mich nur für seine Freundlichkeit revanchieren.\n\nIch würde es zu schätzen wissen, wenn all dies unter uns bliebe. Bewunderern Geschenke zu machen, ist nicht unbedingt statthaft für Dunkle Waldläuferinnen.", sourceObjective = "Bringt die Kapuze von Velonara zu Todesjäger Moorgoth.", completion = "Velonara hat Euch gebeten, mir das persönlich zu geben?\n\n<Moorgoths Augen leuchten auf und er grinst von Ohr zu Ohr.>\n\nSie MAG mich! Sie MAG mich!\n\n<Moorgoth beruhigt sich wieder und räuspert sich.>\n\nDas war sehr freundlich von ihr. Das ist wirklich eine schöne Kapuze. Ich könnte sie als Vorlage für eine Serienproduktion nehmen und die Kopien den anderen Anhängern der dunklen Waldläuferinnen anbieten.\n\nWürdet Ihr Euch gern meine Waren anschauen?", sourceObjectiveStatus = "unverified-source-field" }
quests[45393] = { id = 45393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
