quests[45396] = { id = 45396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[45397] = { id = 45397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuert die Kanonen ab!", description = "Von so einem verdammten Schiffbruch lasse ich mich nicht unterkriegen. Diese verwarzten, stinkenden Dämonensäcke werden sich noch wundern, wenn sie glauben, mich aufhalten zu können.\n\n<Keeshan hustet etwas Salzwasser aus und wischt sich dann den Mund mit dem Ärmel ab.>\n\nArgh... Aber ich glaube, ich könnte eine Pause vertragen. Hier, nehmt diese Leuchtpistole, um damit Artillerieschläge auf den Strand anzufordern. Lasst die Hölle auf diese wertlosen, ziegenfüßigen Mistkerle herabregnen. Ich treffe Euch dann in der Basis wieder, wenn die Mission erledigt ist.", sourceObjective = "Tötet 14 Dämonen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45398] = { id = 45398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschirr in falscher Hand", description = "Diese Narren verwenden die Macht von Raufangs Geschirr, um die Frostwyrms zu unterjochen. Ihr Anführer, Andjor, sitzt da drinnen auf dem Rücken der Brutmutter und lacht uns aus.\n\nDamit hat er sein Leben verwirkt.", sourceObjective = "Tötet Andjor Drachenzähmer und nehmt Raufangs Geschirr an Euch.", progress = "Dieses Geschirr wird uns große Macht verleihen!", completion = "Während meiner Ausbildung erzählte mir Mograine, was wir mit diesem Geschirr anfangen könnten. Ich bin sehr auf die Ergebnisse gespannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45399] = { id = 45399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg mit den Sveldrek", description = "Wie ich gehört habe, läuft das normalerweise so ab: Sterblicher marschiert in Eiskrone ein, wird brutal abgeschlachtet und dann als Mitglied der Geißel wiederbelebt.\n\nDiese Trottel können nicht einfach hier hereinspazieren, machen, was sie wollen, und dann wieder einfach so verschwinden. Jetzt sollen sie so geistlos werden, wie sie sich benehmen.", sourceObjective = "Tötet 8 Vrykul der Sveldrek und lasst sie wiederauferstehen.", completion = "Diese geistlosen Vrykul davontorkeln zu sehen, hat mein lebloses Herz zum Hüpfen gebracht.", sourceObjectiveStatus = "unverified-source-field" }
